-- ScaleUp relational schema (PostgreSQL)
-- Derived from backend/prisma/schema.prisma
-- Money is stored in integer cents. UUIDs are generated by the application/Prisma.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE "User" (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email TEXT NOT NULL UNIQUE,
    password TEXT NOT NULL,
    name TEXT NOT NULL,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "Startup" (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "userId" UUID NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE CASCADE,
    name TEXT NOT NULL,
    seed INTEGER NOT NULL,
    "currentMonth" INTEGER NOT NULL DEFAULT 0 CHECK ("currentMonth" >= 0),
    status TEXT NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'BANKRUPT', 'ACQUIRED')),
    "cashCents" BIGINT NOT NULL DEFAULT 50000000,
    "mrrCents" BIGINT NOT NULL DEFAULT 0,
    "productPriceCents" BIGINT NOT NULL DEFAULT 4900,
    "qualityScore" INTEGER NOT NULL DEFAULT 30 CHECK ("qualityScore" BETWEEN 1 AND 100),
    "founderEquityBps" INTEGER NOT NULL DEFAULT 10000
        CHECK ("founderEquityBps" BETWEEN 0 AND 10000),
    "raisedSeed" BOOLEAN NOT NULL DEFAULT FALSE,
    "raisedSeriesA" BOOLEAN NOT NULL DEFAULT FALSE,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "Turn" (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "startupId" UUID NOT NULL REFERENCES "Startup"(id) ON DELETE RESTRICT ON UPDATE CASCADE,
    month INTEGER NOT NULL CHECK (month >= 1),
    snapshot JSONB NOT NULL,
    decisions JSONB NOT NULL,
    events JSONB NOT NULL,
    ledger JSONB NOT NULL,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT turn_startup_month_unique UNIQUE ("startupId", month)
);

CREATE TABLE "Employee" (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "startupId" UUID NOT NULL REFERENCES "Startup"(id) ON DELETE RESTRICT ON UPDATE CASCADE,
    role TEXT NOT NULL CHECK (role IN ('ENGINEERING', 'SALES', 'MARKETING', 'SUPPORT')),
    "salaryCents" BIGINT NOT NULL CHECK ("salaryCents" >= 0),
    "hiredMonth" INTEGER NOT NULL CHECK ("hiredMonth" >= 0),
    "firedMonth" INTEGER,
    "isActive" BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK ("firedMonth" IS NULL OR "firedMonth" >= "hiredMonth")
);

CREATE TABLE "CustomerCohort" (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "startupId" UUID NOT NULL REFERENCES "Startup"(id) ON DELETE RESTRICT ON UPDATE CASCADE,
    "acquiredMonth" INTEGER NOT NULL CHECK ("acquiredMonth" >= 0),
    "initialCount" INTEGER NOT NULL CHECK ("initialCount" >= 0),
    "currentCount" INTEGER NOT NULL CHECK ("currentCount" >= 0),
    "monthlyPriceCents" BIGINT NOT NULL CHECK ("monthlyPriceCents" >= 0),
    CHECK ("currentCount" <= "initialCount")
);

CREATE TABLE "IdempotencyKey" (
    key TEXT PRIMARY KEY,
    "startupId" UUID NOT NULL REFERENCES "Startup"(id) ON DELETE RESTRICT ON UPDATE CASCADE,
    "turnId" UUID NOT NULL REFERENCES "Turn"(id) ON DELETE RESTRICT ON UPDATE CASCADE,
    response JSONB NOT NULL,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX startup_user_id_idx ON "Startup"("userId");
CREATE INDEX turn_startup_id_idx ON "Turn"("startupId");
CREATE INDEX employee_startup_id_idx ON "Employee"("startupId");
CREATE INDEX cohort_startup_id_idx ON "CustomerCohort"("startupId");
CREATE INDEX idempotency_startup_id_idx ON "IdempotencyKey"("startupId");
CREATE INDEX idempotency_turn_id_idx ON "IdempotencyKey"("turnId");
